    20	        }
    21	    }
    22	
    23	    @Override
    24	    public Price price(Room room, NewReservation request, NightlyCharges charges) {
    25	        return PercentOff.of(charges, DISCOUNT_BY_COMPANY.get(request.companyCode()));
