   179	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
   180	public record ReservationReceipt(
   181	        String title,
   182	        long reservationId,
   183	        String guestName,
   184	        String guestCpf,
   185	        int roomNumber,
   186	        RoomType roomType,
   187	        LocalDate checkIn,
   188	        LocalDate checkOut,
   189	        int nights,
   190	        BigDecimal subtotal,
   191	        BigDecimal discount,
   192	        BigDecimal total) {
   193	
   194	    public ReservationReceipt(Reservation reservation, Room room) {
   195	        this(
   196	                "Comprovante de reserva",
   197	                reservation.id(),
   198	                reservation.guest().name(),
   199	                reservation.guest().cpf(),
   200	                room.number(),
   201	                room.type(),
   202	                reservation.checkIn(),
   203	                reservation.checkOut(),
   204	                reservation.price().nights(),
   205	                reservation.price().subtotal(),
   206	                reservation.price().discount(),
   207	                reservation.price().total());
   208	    }
   209	
   210	    public String text() {
   211	        StringBuilder text = new StringBuilder();
   212	        text.append(title).append(" nº ").append(reservationId).append('\n');
   213	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
   214	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
   215	        text.append("Entrada: ").append(TextFormat.date(checkIn))
   216	                .append(" | Saída: ").append(TextFormat.date(checkOut))
   217	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
   218	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
   219	        if (discount.signum() > 0) {
   220	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
   221	        }
   222	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
   223	        return text.toString();
   224	    }
   225	}
