   228	import java.math.BigDecimal;
   229	import java.time.LocalDate;
   230	import java.time.format.DateTimeFormatter;
   231	import java.util.Locale;
   232	
   233	/** How money and dates are written in the texts the guest reads (Brazilian Portuguese). */
   234	public final class TextFormat {
   235	
   236	    private static final Locale BRAZIL = Locale.forLanguageTag("pt-BR");
   237	    private static final DateTimeFormatter BRAZILIAN_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
   238	
   239	    private TextFormat() {
   240	    }
   241	
   242	    public static String money(BigDecimal amount) {
   243	        return "R$ " + String.format(BRAZIL, "%,.2f", amount);
   244	    }
   245	
   246	    public static String date(LocalDate date) {
   247	        return BRAZILIAN_DATE.format(date);
   248	    }
