   190	        BigDecimal subtotal,
   191	        BigDecimal discount,
   192	        BigDecimal total) {
   193	
   194	    public ReservationReceipt(Reservation reservation, Room room) {
   195	        this(
   196	                "Comprovante de reserva",
   197	                reservation.id(),
   198	                reservation.guest().name(),
   199	                reservation.guest().cpf(),
   200	                room.number(),
   201	                room.type(),
   202	                reservation.checkIn(),
   203	                reservation.checkOut(),
   204	                reservation.price().nights(),
   205	                reservation.price().subtotal(),
   206	                reservation.price().discount(),
