   250	package hotel.reports;
   251	
   252	import hotel.reservations.Reservation;
   253	import hotel.reservations.ReservationStore;
   254	import hotel.rooms.Room;
   255	import hotel.rooms.Rooms;
   256	import java.time.LocalDate;
   257	import java.util.ArrayList;
   258	import java.util.Comparator;
   259	import java.util.List;
   260	
   261	/** Which rooms are occupied on a given night, for the front desk (CSV). */
   262	public final class OccupancyReport {
   263	
   264	    private final Rooms rooms;
   265	    private final ReservationStore store;
   266	
   267	    public OccupancyReport(Rooms rooms, ReservationStore store) {
   268	        this.rooms = rooms;
   269	        this.store = store;
   270	    }
   271	
   272	    public String generate(LocalDate night) {
   273	        List<Reservation> occupying = new ArrayList<>();
   274	        for (Reservation reservation : store.all()) {
   275	            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
   276	            if (reservation.isPaid() && coversNight) {
   277	                occupying.add(reservation);
   278	            }
   279	        }
   280	        occupying.sort(Comparator.comparingInt(Reservation::roomNumber));
   281	
   282	        StringBuilder csv = new StringBuilder();
   283	        csv.append("room,type,reservation,check_in,check_out\n");
   284	        for (Reservation reservation : occupying) {
   285	            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
   286	            csv.append(room.number()).append(',')
   287	                    .append(room.type()).append(',')
   288	                    .append(reservation.id()).append(',')
   289	                    .append(reservation.checkIn()).append(',')
   290	                    .append(reservation.checkOut()).append('\n');
   291	        }
   292	        csv.append("total,").append(occupying.size()).append('/').append(rooms.all().size()).append('\n');
   293	        return csv.toString();
   294	    }
   295	}
   296	package hotel.reports;
   297	
   298	import hotel.reservations.Reservation;
   299	import hotel.reservations.ReservationStore;
   300	import java.math.BigDecimal;
   301	import java.time.YearMonth;
   302	import java.util.ArrayList;
   303	import java.util.Comparator;
   304	import java.util.List;
   305	
   306	/**
   307	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
   308	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
   309	 */
   310	public final class RevenueReport {
   311	
   312	    private final ReservationStore store;
   313	
   314	    public RevenueReport(ReservationStore store) {
   315	        this.store = store;
   316	    }
   317	
   318	    public String generate(YearMonth month) {
   319	        List<Reservation> withRevenue = new ArrayList<>();
   320	        for (Reservation reservation : store.all()) {
   321	            boolean keptMoney = reservation.amountKept().signum() > 0;
   322	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
   323	            if (keptMoney && startsInMonth) {
   324	                withRevenue.add(reservation);
   325	            }
   326	        }
   327	        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
   328	
   329	        StringBuilder csv = new StringBuilder();
   330	        csv.append("reservation,room,check_in,check_out,status,amount\n");
   331	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
   332	        for (Reservation reservation : withRevenue) {
   333	            csv.append(reservation.id()).append(',')
   334	                    .append(reservation.roomNumber()).append(',')
   335	                    .append(reservation.checkIn()).append(',')
   336	                    .append(reservation.checkOut()).append(',')
   337	                    .append(reservation.status()).append(',')
   338	                    .append(reservation.amountKept().toPlainString()).append('\n');
   339	            revenue = revenue.add(reservation.amountKept());
   340	        }
   341	        csv.append("total,").append(revenue.toPlainString()).append('\n');
   342	        return csv.toString();
   343	    }
   344	}
